package ca.yorku.eecs3311.coursepilot.web; import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import ca.yorku.eecs3311.coursepilot.application.service.LearningHistoryService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/courses/{courseId}/history") public class HistoryController {private final StudyAgentFacade facade;private final LearningHistoryService history;public HistoryController(StudyAgentFacade f,LearningHistoryService h){facade=f;history=h;}@GetMapping public String page(@PathVariable Long courseId,Model m){m.addAttribute("course",facade.getCourse(courseId));m.addAttribute("history",history.list(courseId));m.addAttribute("activeNav","history");return "history/index";}}
